import React, { useState, useCallback } from 'react';
import { Calendar, ButtonGroup, Button, Stack } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange: (date: Date) => void;
  initialDate?: Date;
}

const startOfDay = (d: Date): Date => {
  const copy = new Date(d);
  copy.setHours(0, 0, 0, 0);
  return copy;
};

const addDays = (d: Date, days: number): Date => {
  const copy = new Date(d);
  copy.setDate(copy.getDate() + days);
  return copy;
};

const ReportDatePicker: React.FC<ReportDatePickerProps> = ({
  onChange,
  initialDate,
}) => {
  const [selectedDate, setSelectedDate] = useState<Date>(
    startOfDay(initialDate ?? new Date())
  );

  const handleSelect = useCallback(
    (date: Date) => {
      const normalized = startOfDay(date);
      setSelectedDate(normalized);
      onChange(normalized);
    },
    [onChange]
  );

  const quickOptions = [
    { label: 'Сегодня', getDate: () => startOfDay(new Date()) },
    { label: 'Вчера', getDate: () => addDays(startOfDay(new Date()), -1) },
    { label: 'Неделя назад', getDate: () => addDays(startOfDay(new Date()), -7) },
  ];

  const isSameDay = (a: Date, b: Date): boolean =>
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate();

  return (
    <Stack
      direction="column"
      gap="var(--jx-space-3)"
      className="jx-report-date-picker"
    >
      <ButtonGroup aria-label="Быстрый выбор даты отчёта">
        {quickOptions.map((option) => {
          const optionDate = option.getDate();
          const active = isSameDay(optionDate, selectedDate);
          return (
            <Button
              key={option.label}
              variant={active ? 'primary' : 'secondary'}
              size="sm"
              onClick={() => handleSelect(optionDate)}
              aria-pressed={active}
            >
              {option.label}
            </Button>
          );
        })}
      </ButtonGroup>

      <Calendar
        value={selectedDate}
        onChange={handleSelect}
        aria-label="Календарь выбора даты отчёта"
      />
    </Stack>
  );
};

export default ReportDatePicker;

